import 'dart:convert';

import '../app_config.dart';
import '../wallets/crypto_currency/crypto_currency.dart';
import 'logger.dart';

class AddressUtils {
  static final Set<String> recognizedParams = {
    'amount',
    'label',
    'message',
    'memo', // Kerrigan shield memo (ZIP 321: base64url UTF-8 text).
  };

  /// A shield memo as `kerrigan:` URIs carry it (ZIP 321, as Kerrigan
  /// Core reads and writes them): base64url of its UTF-8 text, without
  /// padding.
  static String encodeMemo(String text) =>
      base64Url.encode(utf8.encode(text)).replaceAll("=", "");

  /// The text of a URI memo, or null when it isn't a valid one: not
  /// base64url, over 512 bytes, or not text (Kerrigan Core rejects such
  /// URIs too). Trailing zero padding is dropped.
  static String? decodeMemo(String value) {
    try {
      var v = value.trim();
      // base64url only (Dart's decoder would also take "+" and "/").
      if (v.contains(RegExp(r"[+/]"))) return null;
      v = v.padRight(v.length + (4 - v.length % 4) % 4, "=");
      var bytes = base64Url.decode(v);
      if (bytes.length > 512) return null;
      var end = bytes.length;
      while (end > 0 && bytes[end - 1] == 0) {
        end--;
      }
      bytes = bytes.sublist(0, end);
      if (bytes.contains(0)) return null;
      return utf8.decode(bytes);
    } catch (_) {
      return null;
    }
  }

  /// Return only recognized parameters.
  static Map<String, String> _filterParams(Map<String, String> params) {
    return Map.fromEntries(
      params.entries.where(
        (entry) => recognizedParams.contains(entry.key.toLowerCase()),
      ),
    );
  }

  /// Parses a URI string and returns a map with parsed components.
  static Map<String, String> _parseUri(String uri) {
    final Map<String, String> result = {};
    try {
      final u = Uri.parse(uri);
      if (u.hasScheme) {
        result["scheme"] = u.scheme.toLowerCase();
        result["address"] = u.path;
        result.addAll(_parseQueryParameters(u.queryParameters));
      }
    } catch (e, s) {
      Logging.instance.d(
        "Exception caught in parseUri($uri): $e",
        error: e,
        stackTrace: s,
      );
    }
    return result;
  }

  /// Helper method to parse and normalize query parameters. The values are
  /// already decoded by [Uri.queryParameters]: decoding them again would
  /// turn "%2520" into a space and reject text holding '%'.
  static Map<String, String> _parseQueryParameters(Map<String, String> params) {
    final Map<String, String> result = {};
    params.forEach((key, value) {
      final lowerKey = key.toLowerCase();
      if (recognizedParams.contains(lowerKey)) {
        switch (lowerKey) {
          case 'amount':
            // A plain decimal number. Anything else ("1e3", "1,5") is left
            // out rather than guessed at.
            final amount = value.trim();
            if (RegExp(r"^(\d+\.?\d*|\.\d+)$").hasMatch(amount)) {
              result['amount'] = amount;
            }
            break;
          case 'memo':
            final memo = decodeMemo(value);
            if (memo == null) {
              result['memo_invalid'] = 'true';
            } else {
              result['memo'] = memo;
            }
            break;
          default:
            result[lowerKey] = value;
        }
      } else {
        // Include unrecognized parameters as-is.
        result[key] = value;
      }
    });
    return result;
  }

  /// Centralized method to handle various cryptocurrency URIs and return a common object.
  ///
  /// Returns null on failure to parse
  static PaymentUriData? parsePaymentUri(String uri, {Logging? logging}) {
    try {
      final Map<String, String> parsedData = _parseUri(uri);
      // A memo that can't be read: don't pay without it.
      if (parsedData.containsKey('memo_invalid')) return null;

      // Normalize the URI scheme.
      final String scheme = parsedData['scheme'] ?? '';
      parsedData.remove('scheme');

      // Filter out unrecognized parameters.
      final filteredParams = _filterParams(parsedData);

      return PaymentUriData(
        scheme: scheme,
        address: parsedData['address']!.trim(),
        amount: filteredParams['amount'],
        label: filteredParams['label'],
        message: filteredParams['message'],
        additionalParams: filteredParams,
      );
    } catch (e, s) {
      logging?.i("Invalid payment URI: $uri", error: e, stackTrace: s);
      return null;
    }
  }

  /// Builds a uri string with the given address and query parameters (if any)
  static String buildUriString(
    String scheme,
    String address,
    Map<String, String> params,
  ) {
    // Filter unrecognized parameters.
    final filteredParams = _filterParams(params);
    final memo = filteredParams['memo'];
    if (memo != null) filteredParams['memo'] = encodeMemo(memo);
    String uriString = "$scheme:$address";
    if (filteredParams.isNotEmpty) {
      uriString += Uri(queryParameters: filteredParams).toString();
    }
    return uriString;
  }

  /// returns empty if bad data
  static Map<String, dynamic> decodeQRSeedData(String data) {
    try {
      return Map<String, dynamic>.from(jsonDecode(data) as Map);
    } catch (_) {
      // The words on their own, as most wallets put them in a QR code.
      // (Never logged: the text may be a recovery phrase.)
      final words = data.trim().toLowerCase().split(RegExp(r"\s+"));
      if (words.length >= 12 &&
          words.every((w) => RegExp(r"^[a-z]+$").hasMatch(w))) {
        return {"mnemonic": words};
      }
      return {};
    }
  }

  /// encode mnemonic words to qrcode formatted string
  static String encodeQRSeedData(List<String> words) {
    return jsonEncode({"mnemonic": words});
  }

  /// Method to get CryptoCurrency based on URI scheme.
  static CryptoCurrency? _getCryptoCurrencyByScheme(String scheme) {
    if (AppConfig.coins.map((e) => e.uriScheme).toSet().contains(scheme)) {
      return AppConfig.coins.firstWhere((e) => e.uriScheme == scheme);
    } else {
      return null;
    }
  }
}

class PaymentUriData {
  final String address;
  final String? scheme;
  final String? amount;
  final String? label;
  final String? message;
  final Map<String, String> additionalParams;

  CryptoCurrency? get coin => AddressUtils._getCryptoCurrencyByScheme(
    scheme ?? "", // empty will just return null
  );

  PaymentUriData({
    required this.address,
    this.scheme,
    this.amount,
    this.label,
    this.message,
    required this.additionalParams,
  });

  @override
  String toString() =>
      "PaymentUriData { "
      "coin: $coin, "
      "address: $address, "
      "amount: $amount, "
      "scheme: $scheme, "
      "label: $label, "
      "message: $message, "
      "additionalParams: $additionalParams"
      " }";
}
